<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TPIR Student Register</title><style>body{font-family:Arial,sans-serif;color:#111;margin:24px}h1,h2,p{text-align:center;margin:4px}.toolbar{text-align:right;margin-bottom:18px}button{padding:9px 16px;background:#123b73;color:white;border:0;border-radius:6px}table{width:100%;border-collapse:collapse;margin-top:20px;font-size:11px}th,td{border:1px solid #bbb;padding:7px;text-align:left}th{background:#eef2f7}.muted{color:#555;font-size:11px}@media print{.toolbar{display:none}body{margin:8mm}@page{size:A4 landscape;margin:8mm}tr{break-inside:avoid}}</style></head><body><div class="toolbar"><button onclick="window.print()">Print / Save PDF</button></div><h1>TMSS POLYTECHNIC INSTITUTE</h1><h2>Rangpur · TPIR</h2><p>Student Register · Total: {{count($students)}}</p><table><thead><tr><th>#</th><th>Roll</th><th>Student Name</th><th>Technology</th><th>Semester</th><th>Session</th><th>Shift</th><th>Mobile</th><th>Status</th></tr></thead><tbody>@foreach($students as $i=>$s)<tr><td>{{$i+1}}</td><td>{{$s->student_id}}</td><td>{{$s->name}}</td><td>{{$s->technology}}</td><td>{{$s->semester}}</td><td>{{$s->session}}</td><td>{{$s->shift}}</td><td>{{$s->phone}}</td><td>{{$s->status}}</td></tr>@endforeach</tbody></table><p class="muted" style="margin-top:20px">Printed on {{now()->format('d M Y h:i A')}}</p></body></html>
